/**
 * 场景：宽表检索 / 切片：复合索引列序
 * 适用参数：查询维度 ≥ 3
 * 依赖规则：DATA-SCHM-001, DATA-SQL-001, DATA-SQL-002
 * JDK：21
 */
package com.example.wide.query;

import org.springframework.jdbc.core.JdbcTemplate;
import javax.sql.DataSource;
import java.util.List;

/**
 * 宽表组合查询。
 * 为什么列序是「等值→范围→排序」：B+ 树索引从左到右匹配，一旦碰到范围列（status），
 * 后面的列就只能用不上索引序。把范围列放后面，created_at 的排序就能吃上索引。
 */
public final class CompositeQuery {
    private final JdbcTemplate jdbc;

    public CompositeQuery(DataSource ds) {
        this.jdbc = new JdbcTemplate(ds);
    }

    /** 显式列名，不用 SELECT *；参数占位符绑定，禁止拼接。 */
    public List<Row> query(long tenantId, int region, int category, int status, int limit) {
        // 对应 DDL 索引列序：INDEX idx_query(tenant_id, region, category, status, created_at) INCLUDE(amount)
        // 列序必须与 idx_query 的前缀一致：tenant_id, region, category 是等值，status 是范围。
        String sql = "SELECT id, amount, created_at FROM wide_fact"
                + " WHERE tenant_id = ? AND region = ? AND category = ? AND status = ?"
                + " ORDER BY created_at DESC LIMIT ?";
        return jdbc.query(sql, (rs, n) -> new Row(rs.getLong("id"), rs.getBigDecimal("amount"),
                rs.getTimestamp("created_at").toLocalDateTime()),
                tenantId, region, category, status, limit);
    }

    public record Row(long id, java.math.BigDecimal amount, java.time.LocalDateTime createdAt) {
    }
}

/**
 * 场景：宽表检索 / 切片：覆盖索引
 * 适用参数：P99 < 200ms
 * 依赖规则：DATA-SQL-002, DATA-SQL-001, WEB-CTRL-005
 * JDK：21
 */
package com.example.wide.query;

import org.springframework.jdbc.core.JdbcTemplate;
import javax.sql.DataSource;
import java.util.List;

/**
 * 覆盖索引查询。
 * 为什么绝不用 SELECT *：回表取所有列会让行宽翻倍，P99 直接掉出 200ms。
 * 覆盖索引的价值就是把「查哪些列」和「索引有哪些列」对齐。
 */
public final class CoveringQuery {
    private final JdbcTemplate jdbc;

    public CoveringQuery(DataSource ds) {
        this.jdbc = new JdbcTemplate(ds);
    }

    /** 只 SELECT 覆盖索引里有的列（status, amount），不碰其他宽列。 */
    public List<Row> recent(long tenantId) {
        // LIMIT 必须带上限：没有上限的 pageSize 会一次扫出海量行，缓冲池打穿。
        String sql = "SELECT status, amount, created_at FROM wide_fact"
                + " WHERE tenant_id = ? AND created_at >= ? ORDER BY created_at DESC LIMIT ?";
        return jdbc.query(sql, (rs, n) -> new Row(rs.getInt("status"), rs.getBigDecimal("amount"),
                rs.getTimestamp("created_at").toLocalDateTime()), tenantId, startOfMonth(), 100);
    }

    private java.time.LocalDateTime startOfMonth() {
        return java.time.LocalDateTime.now().withDayOfMonth(1).toLocalDate().atStartOfDay();
    }

    public record Row(int status, java.math.BigDecimal amount, java.time.LocalDateTime createdAt) {
    }
}

/**
 * 场景：宽表检索 / 切片：行存→列存同步
 * 适用参数：数据规模 ≥ 10 亿行
 * 依赖规则：DATA-SCHM-001, REL-CTNR-005, REL-LOG-002
 * JDK：21
 */
package com.example.wide.sync;

import java.util.List;

/**
 * 行存热表 → 列存分析表的同步作业。
 * 为什么异步而非双写：双写要保证两个存储的事务一致，几乎做不到且把写路径拖死。
 * 异步同步有延迟但写路径干净，列存分析本就接受分钟级时延。
 */
public final class RowToColumnSync {
    private final ChangeLogSource source;
    private final ColumnStoreSink sink;

    public RowToColumnSync(ChangeLogSource source, ColumnStoreSink sink) {
        this.source = source;
        this.sink = sink;
    }

    /** 批量拉变更、批量写列存。逐条写列存会丧失向量化批处理的优势。 */
    public int syncBatch() {
        List<Change> batch = source.poll(5000);
        if (batch.isEmpty()) {
            return 0;
        }
        // 批量写入列存：列存的优势在批，逐条 INSERT 等于自废武功。
        sink.appendBatch(batch);
        source.ack(batch);
        return batch.size();
    }

    public interface ChangeLogSource {
        List<Change> poll(int max);

        void ack(List<Change> batch);
    }

    public interface ColumnStoreSink {
        void appendBatch(List<Change> batch);
    }

    public record Change(long id, int region, int category, java.math.BigDecimal amount) {
    }
}

