-- 按时间分区：历史数据 DROP PARTITION 是元数据操作秒级完成，DELETE 是行操作亿级要几小时。
ALTER TABLE wide_fact
  PARTITION BY RANGE (TO_DAYS(created_at)) (
    PARTITION p_hot  VALUES LESS THAN (TO_DAYS(NOW()) - 90),
    PARTITION p_cold VALUES LESS THAN MAXVALUE
  );

-- 归档：把 90 天前数据导出到对象存储/列存后，DROP 旧分区。先导出再 DROP，顺序反了数据丢。
-- 冷数据查询走列存表 wide_columar，不经过热表。
ALTER TABLE wide_fact DROP PARTITION p_cold;

