/**
 * 场景：宽表检索 / 切片：冷热分层
 * 适用参数：冷热分层需求 = 需分层 / 混合
 * 依赖规则：DATA-SCHM-001, REL-CTNR-005, REL-LOG-002
 * JDK：21
 */
package com.example.wide.tier;

import java.time.Instant;
import java.time.temporal.ChronoUnit;

/**
 * 冷热分层路由。
 * 为什么按时间而不是访问频率：宽表历史查询分布极度偏斜（99% 查近期），
 * 按时间分层实现简单、效果足够；访问频率统计本身要额外存储与计算。
 */
public final class WideTierRouter {
    /** 热层保留天数。超过即降级到冷存储。 */
    private static final int HOT_DAYS = 90;

    private WideTierRouter() {
    }

    /** 该记录应落在哪一层。查询时先打热表，未命中再打冷列存。 */
    public static Tier tierOf(Instant createdAt, Instant now) {
        long age = ChronoUnit.DAYS.between(createdAt, now);
        return age <= HOT_DAYS ? Tier.HOT : Tier.COLD;
    }

    /** 是否到了归档时机：冷数据定期导出后删除热表分区。 */
    public static boolean shouldArchive(Instant createdAt, Instant now) {
        // 归档作业失败必须跳过而非裸删，否则冷数据凭空消失。
        return ChronoUnit.DAYS.between(createdAt, now) > HOT_DAYS;
    }

    public enum Tier {
        HOT, COLD
    }
}

