/**
 * 场景：宽表检索 / 切片：位图索引组合查询
 * 适用参数：查询维度 = 8 维
 * 依赖规则：DATA-SCHM-001, DATA-SQL-001, REL-EXCP-002
 * JDK：21
 */
package com.example.wide.bitmap;

import java.util.BitSet;

/**
 * 多条件组合的位图求交。
 * 为什么用位图：8 维低基数列，每个列建一个 BitSet（行号→是否命中），
 * 组合条件就是多个 BitSet 做 AND，比嵌套循环过滤快几个数量级。
 */
public final class BitmapCombine {
    /**
     * 多个条件的位图求交：AND 语义。
     * 空集合（无约束的条件）直接跳过，不能当成「全不匹配」。
     */
    public static BitSet and(BitSet... masks) {
        BitSet result = null;
        for (BitSet m : masks) {
            if (m == null) {
                continue; // 该条件无约束，跳过而不是当空集
            }
            if (result == null) {
                result = (BitSet) m.clone();
            } else {
                result.and(m);
            }
        }
        return result == null ? new BitSet() : result;
    }

    /** OR 语义（任一条件命中）。 */
    public static BitSet or(BitSet... masks) {
        BitSet result = new BitSet();
        for (BitSet m : masks) {
            if (m != null) {
                result.or(m);
            }
        }
        return result;
    }
}

/**
 * 场景：宽表检索 / 切片：谓词下推与预聚合
 * 适用参数：查询并发 ≥ 1 万
 * 依赖规则：DATA-SQL-002, WEB-CTRL-005, REL-LOG-002
 * JDK：21
 */
package com.example.wide.pushdown;

import org.springframework.jdbc.core.JdbcTemplate;
import javax.sql.DataSource;
import java.util.List;

/**
 * 高并发检索：尽量让过滤发生在存储层。
 * 为什么应用层拉全量再筛不可取：高并发下每请求多传几万行，网络与内存同时爆。
 * 查询列必须显式、LIMIT 必须带上限。
 */
public final class PushdownQuery {
    private final JdbcTemplate jdbc;

    public PushdownQuery(DataSource ds) {
        this.jdbc = new JdbcTemplate(ds);
    }

    /** 走预聚合表：查询直接读汇总结果，不扫基表。 */
    public List<RegionRow> byRegion(long tenantId, java.time.LocalDate day) {
        String sql = "SELECT region, cnt, amount_sum FROM wide_rollup_region"
                + " WHERE tenant_id = ? AND stat_date = ? ORDER BY cnt DESC LIMIT ?";
        return jdbc.query(sql, (rs, n) -> new RegionRow(rs.getInt("region"),
                rs.getLong("cnt"), rs.getBigDecimal("amount_sum")), tenantId, day, 100);
    }

    public record RegionRow(int region, long cnt, java.math.BigDecimal amountSum) {
    }
}

/**
 * 场景：宽表检索 / 切片：keyset 分页
 * 适用参数：数据规模 ≥ 1 亿行
 * 依赖规则：DATA-SQL-002, WEB-DTO-001, REL-EXCP-002
 * JDK：21
 */
package com.example.wide.page;

import org.springframework.jdbc.core.JdbcTemplate;
import javax.sql.DataSource;
import java.time.LocalDateTime;
import java.util.List;

/**
 * keyset（游标）分页。
 * 为什么不用 OFFSET：OFFSET N 的代价是「读出前 N 行再丢弃」，
 * keyset 代价恒定——靠索引直接定位游标位置。两者在 1 万行差别看不出，亿级是两个数量级。
 */
public final class WideKeysetPage {
    private static final int MAX_PAGE = 200;

    private final JdbcTemplate jdbc;

    public WideKeysetPage(DataSource ds) {
        this.jdbc = new JdbcTemplate(ds);
    }

    public record Keyset(LocalDateTime createdAt, long id) {
    }

    public List<Row> page(long tenantId, Keyset cursor, int pageSize) {
        int size = Math.min(Math.max(pageSize, 1), MAX_PAGE);
        String base = "SELECT id, tenant_id, amount, created_at FROM wide_fact"
                + " WHERE tenant_id = ?";
        if (cursor == null) {
            return jdbc.query(base + " ORDER BY created_at DESC, id DESC LIMIT ?",
                    (rs, n) -> toRow(rs), tenantId, size);
        }
        // 半开区间 (created_at, id) < (?, ?)：索引键整体比较，能完整吃上复合索引。
        return jdbc.query(base + " AND (created_at, id) < (?, ?) ORDER BY created_at DESC, id DESC LIMIT ?",
                (rs, n) -> toRow(rs), tenantId, cursor.createdAt(), cursor.id(), size);
    }

    private Row toRow(java.sql.ResultSet rs) throws java.sql.SQLException {
        return new Row(rs.getLong("id"), rs.getLong("tenant_id"),
                rs.getBigDecimal("amount"), rs.getTimestamp("created_at").toLocalDateTime());
    }

    public record Row(long id, long tenantId, java.math.BigDecimal amount, LocalDateTime createdAt) {
    }
}

/**
 * 场景：宽表检索 / 切片：物化视图刷新
 * 适用参数：P99 < 50ms
 * 依赖规则：SVC-TX-001, REL-RETRY-001, REL-LOG-001
 * JDK：21
 */
package com.example.wide.mv;

import org.springframework.jdbc.core.JdbcTemplate;
import javax.sql.DataSource;

/**
 * 物化视图刷新作业。
 * 为什么用「先写临时表再 RENAME」而不是「DELETE 再 INSERT」：
 * 后者在刷新中途会让读者看到半截/空数据，且 DELETE+INSERT 不是原子的。
 * RENAME 是元数据操作，读者要么看到旧表要么看到新表，不会出现中间态。
 */
public final class MaterializedViewRefresher {
    private final JdbcTemplate jdbc;

    public MaterializedViewRefresher(DataSource ds) {
        this.jdbc = new JdbcTemplate(ds);
    }

    /** 刷新：算进临时表，再原子 rename 覆盖。失败只记日志，不抛异常中断整批。 */
    public void refresh() {
        try {
            jdbc.update("INSERT INTO mv_top_region_day_tmp"
                    + " SELECT tenant_id, CURDATE(), region, COUNT(*), SUM(amount)"
                    + " FROM wide_fact WHERE created_at >= CURDATE() - INTERVAL 1 DAY GROUP BY tenant_id, region");
            // 原子切换：读者不会看到刷新中途的半截数据
            jdbc.update("RENAME TABLE mv_top_region_day TO mv_top_region_day_old,"
                    + " mv_top_region_day_tmp TO mv_top_region_day");
        } catch (RuntimeException ex) {
            // 刷新失败不能让调度作业崩；记日志，下次重跑（INSERT 幂等可重跑）。
            org.slf4j.LoggerFactory.getLogger(MaterializedViewRefresher.class)
                    .error("mv refresh failed: {}", ex.toString());
        }
    }
}
